/**
 * Copies MapLibre's Web Worker (and the shared chunk it imports) out of
 * node_modules into `public/maplibre/`.
 *
 * Turbopack mis-compiles MapLibre v6's internal worker-URL lookup — it rewrites
 * `new URL(workerFile, import.meta.url)` to point at the main library instead of
 * the worker, so `new Worker(url, { type: 'module' })` receives HTML and the map
 * never starts. `lib/map-style.ts` documents the failure in full.
 *
 * The fix is MapLibre's official `setWorkerUrl()` override, which needs the
 * worker served from a URL we control. This script keeps that copy honest: it
 * runs on `postinstall`, so upgrading maplibre-gl cannot leave a stale worker
 * behind, and it refuses to run silently if the source files move.
 *
 * Both files are required together — `maplibre-gl-worker.mjs` begins with
 * `import ... from "./maplibre-gl-shared.mjs"`, so they must stay siblings.
 */

import { mkdir, readFile, writeFile } from "node:fs/promises";
import { createRequire } from "node:module";
import { dirname, join, resolve } from "node:path";

const FILES = ["maplibre-gl-worker.mjs", "maplibre-gl-shared.mjs"];
const OUT_DIR = resolve(import.meta.dirname, "..", "public", "maplibre");

const require = createRequire(import.meta.url);

async function main() {
  let distDir;
  let version;
  try {
    const pkgPath = require.resolve("maplibre-gl/package.json");
    distDir = join(dirname(pkgPath), "dist");
    version = JSON.parse(await readFile(pkgPath, "utf8")).version;
  } catch {
    // Not an error: `postinstall` can run before deps exist, or in a workspace
    // that legitimately has no maplibre-gl. Nothing to sync.
    console.log("[maplibre-worker] maplibre-gl not installed — nothing to sync.");
    return;
  }

  await mkdir(OUT_DIR, { recursive: true });

  for (const file of FILES) {
    const from = join(distDir, file);
    try {
      // The `.map` files are deliberately NOT copied — they are large and only
      // useful for debugging MapLibre itself. So the trailing sourceMappingURL
      // comment is stripped too, otherwise every page load with devtools open
      // fires a 404 for a map file that was never shipped.
      const source = await readFile(from, "utf8");
      const stripped = source.replace(/^\/\/# sourceMappingURL=.*$/gm, "").trimEnd() + "\n";
      await writeFile(join(OUT_DIR, file), stripped, "utf8");
    } catch (cause) {
      // Loud, not silent: a missing worker means the map fails at runtime with a
      // confusing MIME error, so this must break the install rather than pass.
      throw new Error(
        `[maplibre-worker] could not copy ${file} from ${distDir}. ` +
          `maplibre-gl ${version} may have changed its dist layout — check ` +
          `lib/map-style.ts (WORKER_URL) before upgrading.\n${cause}`,
      );
    }
  }

  // Stamp the version so a stale copy is obvious on inspection and in diffs.
  await writeFile(
    join(OUT_DIR, "VERSION"),
    `maplibre-gl ${version}\n` +
      `Generated by scripts/sync-maplibre-worker.mjs — do not edit by hand.\n` +
      `See lib/map-style.ts (WORKER_URL) for why these files are served locally.\n`,
    "utf8",
  );

  console.log(`[maplibre-worker] synced ${FILES.join(", ")} from maplibre-gl ${version}`);
}

await main();
